contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 role0, uint256 delay) public {
        bytes32 adminRole = c.TIMELOCK_ADMIN_ROLE();
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 minDelay = c.getMinDelay();
        bytes32 salt = keccak256(abi.encode(role0));
        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        bool ok = delay >= minDelay;
        bool reverted;
        if (ok) {
            reverted = false;
            c.schedule(address(this), 0, "", bytes32(0), salt, delay);
        } else {
            try c.schedule(address(this), 0, "", bytes32(0), salt, delay) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        uint256 ts = c.getTimestamp(id);
        if (!reverted) {
            assert(ts == block.timestamp + delay && c.isOperation(id));
        } else {
            assert(!c.isOperation(id));
        }
    }
    receive() external payable {}
}

