contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        bool scheduledReverted;
        if (delay < minDelay) {
            try c.schedule(target, value, data, predecessor, salt, delay) { scheduledReverted = false; } catch { scheduledReverted = true; }
            assert(scheduledReverted && !c.isOperation(id));
        } else {
            c.schedule(target, value, data, predecessor, salt, delay);
            assert(c.getTimestamp(id) == block.timestamp + delay && c.isOperationPending(id));
        }
    }
    receive() external payable {}
}

