contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        // Grant this contract the proposer role (deployer holds the admin role).
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay);

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id));

        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 ts = c.getTimestamp(id);
        assert(ts == block.timestamp + delay && c.isOperation(id) && (delay < 1 || c.isOperationPending(id)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address target,
        uint256 delay
    ) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        require(delay >= c.getMinDelay());
        require(delay >= 1);

        bytes32 id = c.hashOperation(target, 0, "", bytes32(0), bytes32(0));
        require(!c.isOperation(id));

        c.schedule(target, 0, "", bytes32(0), bytes32(0), delay);
        require(c.isOperationPending(id));

        c.cancel(id);

        assert(c.getTimestamp(id) == 0 && !c.isOperation(id) && !c.isOperationPending(id));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public {
        require(account != address(this));

        // We (deployer) hold TIMELOCK_ADMIN_ROLE; drop it so we are no longer admin.
        c.revokeRole(c.TIMELOCK_ADMIN_ROLE(), address(this));

        bool reverted;
        try c.grantRole(c.PROPOSER_ROLE(), account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && !c.hasRole(c.PROPOSER_ROLE(), account));
    }

    receive() external payable {}
}

